/* ===== 11a_pet_asset.js ===== */
/* 卢克之光 V5.6 — 3D CG 雕像迪迦全形态资产 + 三层可动金属神光棒 + 边界洪泛透明抠图缓存 */
var AR6_PET_ASSETS = {
  multi: {
    w: 145, h: 360, thresh: 16,
    timer: { x: 42.0, y: 24.4, w: 7.4, h: 4.0 },
    raw: 'data:image/jpeg;base64,'
  },
  glitter: {
    w: 173, h: 360, thresh: 16,
    timer: { x: 53.0, y: 25.0, w: 6.4, h: 4.1 },
    raw: 'data:image/jpeg;base64,'
  },
  abyss: {
    w: 211, h: 360, thresh: 7,
    timer: { x: 30.0, y: 23.6, w: 5.0, h: 3.9 },
    raw: 'data:image/jpeg;base64,'
  },
  spBody: {
    w: 162, h: 320, thresh: 16,
    raw: 'data:image/jpeg;base64,'
  },
  spLwing: {
    w: 162, h: 320, thresh: 16,
    raw: 'data:image/jpeg;base64,'
  },
  spRwing: {
    w: 162, h: 320, thresh: 16,
    raw: 'data:image/jpeg;base64,'
  }
};
var AR6_PET_BG = 'url("' + AR6_PET_ASSETS.multi.raw + '")';
var AR6_PET_ALPHA_CACHE = {};
var AR6_PET_ALPHA_WAIT = {};

function ar6MatteSprite(key, cb) {
  var item = AR6_PET_ASSETS && AR6_PET_ASSETS[key];
  if (!item || !item.raw) { if (cb) cb(''); return; }
  if (AR6_PET_ALPHA_CACHE[key]) { if (cb) cb(AR6_PET_ALPHA_CACHE[key]); return; }
  if (AR6_PET_ALPHA_WAIT[key]) { if (cb) AR6_PET_ALPHA_WAIT[key].push(cb); return; }
  AR6_PET_ALPHA_WAIT[key] = cb ? [cb] : [];
  function done(url) {
    AR6_PET_ALPHA_CACHE[key] = url || item.raw;
    var q = AR6_PET_ALPHA_WAIT[key] || [];
    delete AR6_PET_ALPHA_WAIT[key];
    for (var i = 0; i < q.length; i++) { try { q[i](AR6_PET_ALPHA_CACHE[key]); } catch (e0) {} }
  }
  try {
    var W = (DOC && DOC.defaultView) || HOST;
    var ImgCtor = (W && W.Image) || (typeof Image === 'function' ? Image : null);
    if (!ImgCtor || !DOC || typeof DOC.createElement !== 'function') { done(item.raw); return; }
    var testCv = DOC.createElement('canvas');
    if (!testCv || typeof testCv.getContext !== 'function') { done(item.raw); return; }
    var img = new ImgCtor();
    img.onload = function () {
      try {
        var w = img.naturalWidth || item.w, h = img.naturalHeight || item.h;
        var cv = DOC.createElement('canvas');
        cv.width = w; cv.height = h;
        var ctx = cv.getContext('2d', { willReadFrequently: true });
        if (!ctx || typeof ctx.getImageData !== 'function') { done(item.raw); return; }
        ctx.drawImage(img, 0, 0, w, h);
        var id = ctx.getImageData(0, 0, w, h);
        var d = id.data;
        var total = w * h;
        var bg = new Uint8Array(total);
        var vis = new Uint8Array(total);
        var q = new Int32Array(total);
        var head = 0, tail = 0, th = item.thresh || 16;
        function push(x, y) {
          if (x < 0 || y < 0 || x >= w || y >= h) return;
          var p = y * w + x;
          if (vis[p]) return;
          var i = p * 4;
          var mx = d[i] > d[i + 1] ? (d[i] > d[i + 2] ? d[i] : d[i + 2]) : (d[i + 1] > d[i + 2] ? d[i + 1] : d[i + 2]);
          if (mx <= th) { vis[p] = 1; bg[p] = 1; q[tail++] = p; }
        }
        for (var x0 = 0; x0 < w; x0++) { push(x0, 0); push(x0, h - 1); }
        for (var y0 = 0; y0 < h; y0++) { push(0, y0); push(w - 1, y0); }
        while (head < tail) {
          var cur = q[head++];
          var cx = cur % w, cy = (cur / w) | 0;
          push(cx + 1, cy); push(cx - 1, cy); push(cx, cy + 1); push(cx, cy - 1);
        }
        /* 防指纹保护/未解码画布回读全黑误抠：若透明占比 >=96% 则回退原图，杜绝立绘整张透明消失 */
        if (tail >= total * 0.96) { done(item.raw); return; }
        for (var p2 = 0; p2 < total; p2++) {
          if (bg[p2]) { d[p2 * 4 + 3] = 0; continue; }
          var xx = p2 % w, yy = (p2 / w) | 0;
          var near = (xx > 0 && bg[p2 - 1]) || (xx + 1 < w && bg[p2 + 1]) || (yy > 0 && bg[p2 - w]) || (yy + 1 < h && bg[p2 + w]);
          if (near) {
            var ii = p2 * 4;
            var m2 = d[ii] > d[ii + 1] ? (d[ii] > d[ii + 2] ? d[ii] : d[ii + 2]) : (d[ii + 1] > d[ii + 2] ? d[ii + 1] : d[ii + 2]);
            var al = Math.round(((m2 - th) / 26) * 255);
            d[ii + 3] = al < 0 ? 0 : (al > 255 ? 255 : al);
          }
        }
        ctx.putImageData(id, 0, 0);
        var outUrl = cv.toDataURL('image/png');
        done((outUrl && outUrl.indexOf('data:image/png;base64,') === 0 && outUrl.length > 64) ? outUrl : item.raw);
      } catch (eMat) { done(item.raw); }
    };
    img.onerror = function () { done(item.raw); };
    img.src = item.raw;
  } catch (eAll) { done(item.raw); }
}